//! SPEC: canon §1.9 sine table and angles, doc 02 §4.3
//!
//! Angles are `Bam` (`u16`, 65536 = one full turn). Sines and cosines are
//! Q2.30 `i32` values in `-2^30..=2^30`, read from the committed table
//! [`SIN_T`] generated by `tools/gen_trig.py`.

use crate::fx::Fx;
use crate::geom::Fx3;

pub use crate::trig_table::SIN_T;

/// SPEC: canon §1.2 `Bam`: binary angle, 65536 = one full turn.
pub type Bam = u16;

/// SPEC: canon §1.9. Q2.30 one (`2^30`), the value of `sin_bam(16384)`.
pub const Q30_ONE: i32 = 1 << 30;

/// SPEC: canon §1.9. A quarter turn in Bam.
pub const BAM_QUARTER: Bam = 16_384;

/// SPEC: canon §1.9. A half turn in Bam.
pub const BAM_HALF: Bam = 32_768;

/// SPEC: canon §1.9. Pitch is clamped to `-PITCH_LIMIT..=PITCH_LIMIT` (about 87.9 degrees).
pub const PITCH_LIMIT: i16 = 16_000;

/// SPEC: canon §1.9 `sin_bam(a)`: `q = a >> 14`, `r = a & 0x3FFF`;
/// `q = 0 -> T[r]`, `q = 1 -> T[16384 - r]`, `q = 2 -> -T[r]`, `q = 3 -> -T[16384 - r]`.
/// Result is Q2.30.
#[inline]
#[must_use]
pub fn sin_bam(a: Bam) -> i32 {
    let q = a >> 14;
    let r = usize::from(a & 0x3FFF);
    match q {
        0 => SIN_T[r],
        1 => SIN_T[16_384 - r],
        2 => -SIN_T[r],
        _ => -SIN_T[16_384 - r],
    }
}

/// SPEC: canon §1.9 `cos_bam(a) = sin_bam(a.wrapping_add(16384))`. Q2.30.
#[inline]
#[must_use]
pub fn cos_bam(a: Bam) -> i32 {
    sin_bam(a.wrapping_add(BAM_QUARTER))
}

/// SPEC: canon §1.9. Product of two Q2.30 factors shifted right by 30
/// (arithmetic shift, floor). For table values the result stays in
/// `-2^30..=2^30`.
#[inline]
#[must_use]
pub fn q30_mul(a: i32, b: i32) -> i32 {
    // |a|, |b| <= 2^30 for table values, so the product fits in i64 and the
    // shifted result in i32; the narrowing is still checked.
    let p = (i64::from(a) * i64::from(b)) >> 30;
    i32::try_from(p).expect("q30_mul: result out of i32 range")
}

/// SPEC: canon §1.9 forward vector in Q2.30:
/// `fwd(yaw, pitch) = (-sin_bam(yaw)·cos_bam(pitch), sin_bam(pitch), -cos_bam(yaw)·cos_bam(pitch))`,
/// each two-factor product shifted right by 30.
///
/// `pitch` is the `i16` reinterpretation of its `Bam` (canon §1.9); it is fed
/// to `sin_bam`/`cos_bam` as `pitch as u16` (two's complement). This function
/// does not clamp pitch; callers keep it in `-16000..=16000` (see
/// [`clamp_pitch`]). The minus sign belongs to the first factor: the product
/// is `(-sin) * cos`, then shifted (floor), as the canon writes it.
#[inline]
#[must_use]
pub fn fwd(yaw: Bam, pitch: i16) -> [i32; 3] {
    let p = pitch_as_bam(pitch);
    let cp = cos_bam(p);
    [
        q30_mul(-sin_bam(yaw), cp),
        sin_bam(p),
        q30_mul(-cos_bam(yaw), cp),
    ]
}

/// SPEC: canon §1.9 and doc 02 §4.3. The forward vector as an `Fx3`, each
/// Q2.30 component converted by `Fx::from_raw((q30 as i64) << 2)`.
#[inline]
#[must_use]
pub fn fwd_fx(yaw: Bam, pitch: i16) -> Fx3 {
    let [x, y, z] = fwd(yaw, pitch);
    Fx3::new(q30_to_fx(x), q30_to_fx(y), q30_to_fx(z))
}

/// SPEC: doc 02 §4.3. Convert a Q2.30 value to `Fx`: `Fx::from_raw((q30 as i64) << 2)`.
/// Exact for every `i32`.
#[inline]
#[must_use]
pub const fn q30_to_fx(q30: i32) -> Fx {
    Fx::from_raw((q30 as i64) << 2)
}

/// SPEC: canon §1.9 `ang_diff(a, b) = (a.wrapping_sub(b) as i16).unsigned_abs()`,
/// the unsigned shortest angular distance in `0..=32768`.
#[inline]
#[must_use]
pub const fn ang_diff(a: Bam, b: Bam) -> u16 {
    // `as i16` is the two's-complement reinterpretation the canon specifies.
    (a.wrapping_sub(b) as i16).unsigned_abs()
}

/// SPEC: canon §1.9 Bam arithmetic wraps: `a.wrapping_add(b)`.
#[inline]
#[must_use]
pub const fn bam_add(a: Bam, b: Bam) -> Bam {
    a.wrapping_add(b)
}

/// SPEC: canon §1.9 Bam arithmetic wraps: `a.wrapping_sub(b)`.
#[inline]
#[must_use]
pub const fn bam_sub(a: Bam, b: Bam) -> Bam {
    a.wrapping_sub(b)
}

/// SPEC: canon §1.9. Pitch is the `i16` reinterpretation of its `Bam`; this
/// converts a `Bam` to that `i16` and clamps it to `-16000..=16000`.
#[inline]
#[must_use]
pub const fn pitch_from_bam(b: Bam) -> i16 {
    clamp_pitch(b as i16)
}

/// SPEC: canon §1.9. The `Bam` whose `i16` reinterpretation is `pitch`.
#[inline]
#[must_use]
pub const fn pitch_as_bam(pitch: i16) -> Bam {
    pitch as u16
}

/// SPEC: canon §1.9. Clamp a pitch to `-16000..=16000`.
#[inline]
#[must_use]
pub const fn clamp_pitch(pitch: i16) -> i16 {
    if pitch < -PITCH_LIMIT {
        -PITCH_LIMIT
    } else if pitch > PITCH_LIMIT {
        PITCH_LIMIT
    } else {
        pitch
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn table_shape() {
        assert_eq!(SIN_T.len(), 16_385);
        assert_eq!(SIN_T[0], 0);
        assert_eq!(SIN_T[16_384], 1_073_741_824);
        for i in 1..SIN_T.len() {
            assert!(SIN_T[i] > SIN_T[i - 1], "not strictly increasing at {i}");
        }
    }

    #[test]
    fn table_spot_values() {
        // Doc 02 §4.3 spot values.
        assert_eq!(SIN_T[1], 102_944);
        assert_eq!(SIN_T[2], 205_887);
        assert_eq!(SIN_T[4096], 410_903_207);
        assert_eq!(SIN_T[8192], 759_250_125);
        assert_eq!(SIN_T[10_923], 929_904_853);
        assert_eq!(SIN_T[16_383], 1_073_741_819);
        assert_eq!(SIN_T[16_384], 1_073_741_824);
    }

    #[test]
    fn table_integrity_hash() {
        // Doc 02 §4.3 integrity check: BLAKE3 of the 16,385 values as little-endian i32.
        let mut h = blake3::Hasher::new();
        for v in SIN_T.iter() {
            h.update(&v.to_le_bytes());
        }
        let hex = h.finalize().to_hex();
        assert_eq!(hex.as_str(), "d2612a42910edad3b81095ad0be154d6076c5c33771916cbbea2ded40419ec11");
    }

    #[test]
    #[allow(clippy::float_arithmetic, clippy::disallowed_types)]
    fn table_cross_check_against_libm() {
        // Cross-check only: the expected values come from the committed table.
        // f64 sin is accurate to well under 1e-9 here, so the rounded value
        // must agree to within 1 unit everywhere.
        for (i, &v) in SIN_T.iter().enumerate() {
            let x: f64 = (2.0 * core::f64::consts::PI * (i as f64) / 65536.0).sin() * 1_073_741_824.0;
            assert!((x - f64::from(v)).abs() <= 0.5 + 1e-6, "T[{i}] = {v}, libm {x}");
        }
    }

    #[test]
    fn canon_t12_trigonometry() {
        // Canon §21 test 12.
        assert_eq!(sin_bam(0), 0);
        assert_eq!(sin_bam(16_384), 1 << 30);
        assert_eq!(cos_bam(0), 1 << 30);
        assert_eq!(sin_bam(49_152), -(1 << 30));
    }

    #[test]
    fn folding_rule_quadrants() {
        assert_eq!(sin_bam(32_768), 0);
        assert_eq!(cos_bam(16_384), 0);
        assert_eq!(cos_bam(32_768), -(1 << 30));
        assert_eq!(cos_bam(49_152), 0);
        assert_eq!(sin_bam(8192), 759_250_125);
        assert_eq!(sin_bam(16_384 + 8192), 759_250_125);
        assert_eq!(sin_bam(32_768 + 8192), -759_250_125);
        assert_eq!(sin_bam(49_152 + 8192), -759_250_125);
        assert_eq!(sin_bam(1), 102_944);
        assert_eq!(sin_bam(65_535), -102_944);
        assert_eq!(cos_bam(65_535), 1_073_741_819);
    }

    #[test]
    fn fwd_examples() {
        // Doc 02 §4.3: yaw 16384 faces west (-X).
        assert_eq!(fwd(16_384, 0), [-(1 << 30), 0, 0]);
        // Yaw 0 faces -Z (canon §1.9).
        assert_eq!(fwd(0, 0), [0, 0, -(1 << 30)]);
        assert_eq!(fwd(32_768, 0), [0, 0, 1 << 30]);
        assert_eq!(fwd(49_152, 0), [1 << 30, 0, 0]);
        // Straight-ish up at the pitch clamp.
        let up = fwd(0, PITCH_LIMIT);
        assert_eq!(up[1], sin_bam(16_000));
        assert_eq!(up[0], 0);
        assert!(up[2] < 0);
        // Looking down mirrors y.
        let down = fwd(0, -PITCH_LIMIT);
        assert_eq!(down[1], -sin_bam(16_000));
        assert_eq!(down[2], up[2]);
        // 45 degrees: product (-s)*c floored.
        let d = fwd(8192, 0);
        assert_eq!(d, [-759_250_125, 0, -759_250_125]);
        let e = fwd(8192, 8192);
        let expect = ((-759_250_125i64) * 759_250_125) >> 30;
        assert_eq!(e[0] as i64, expect);
        assert_eq!(e[2] as i64, expect);
        assert_eq!(e[1], 759_250_125);
    }

    #[test]
    fn fwd_fx_converts() {
        let v = fwd_fx(16_384, 0);
        assert_eq!(v.x, Fx::from_int(-1));
        assert_eq!(v.y, Fx::ZERO);
        assert_eq!(v.z, Fx::ZERO);
        assert_eq!(q30_to_fx(1 << 30), Fx::ONE);
        assert_eq!(q30_to_fx(-(1 << 29)), Fx::from_raw(-(1 << 31)));
    }

    #[test]
    fn ang_diff_examples() {
        assert_eq!(ang_diff(0, 0), 0);
        assert_eq!(ang_diff(10, 65_530), 16);
        assert_eq!(ang_diff(65_530, 10), 16);
        assert_eq!(ang_diff(0, 32_768), 32_768);
        assert_eq!(ang_diff(32_768, 0), 32_768);
        assert_eq!(ang_diff(16_384, 0), 16_384);
        assert_eq!(ang_diff(0, 16_384), 16_384);
        assert_eq!(bam_add(65_535, 2), 1);
        assert_eq!(bam_sub(1, 2), 65_535);
    }

    #[test]
    fn pitch_helpers() {
        assert_eq!(clamp_pitch(16_001), 16_000);
        assert_eq!(clamp_pitch(-32_768), -16_000);
        assert_eq!(pitch_from_bam(65_535), -1);
        assert_eq!(pitch_from_bam(20_000), 16_000);
        assert_eq!(pitch_from_bam(40_000), -16_000);
        assert_eq!(pitch_as_bam(-1), 65_535);
    }

    proptest! {
        #[test]
        fn sin_range_and_symmetry(a in any::<u16>()) {
            let s = sin_bam(a);
            prop_assert!((-(1 << 30)..=(1 << 30)).contains(&s));
            // sin(-a) = -sin(a)
            prop_assert_eq!(sin_bam(a.wrapping_neg()), -s);
            // sin(a + half) = -sin(a)
            prop_assert_eq!(sin_bam(a.wrapping_add(BAM_HALF)), -s);
            // sin(half - a) = sin(a)
            prop_assert_eq!(sin_bam(BAM_HALF.wrapping_sub(a)), s);
        }

        #[test]
        fn cos_even_and_pythagoras(a in any::<u16>()) {
            prop_assert_eq!(cos_bam(a.wrapping_neg()), cos_bam(a));
            let s = i64::from(sin_bam(a));
            let c = i64::from(cos_bam(a));
            // s^2 + c^2 = 2^60 within the table's rounding error (|e| <= 0.5 each).
            let err = (s * s + c * c - (1i64 << 60)).abs();
            prop_assert!(err <= 1i64 << 31, "err {}", err);
        }

        #[test]
        fn sin_monotone_first_quadrant(a in 0u16..16_384) {
            prop_assert!(sin_bam(a) < sin_bam(a + 1));
        }

        #[test]
        fn ang_diff_range_and_symmetry(a in any::<u16>(), b in any::<u16>()) {
            let d = ang_diff(a, b);
            prop_assert!(d <= 32_768);
            prop_assert_eq!(d, ang_diff(b, a));
            prop_assert_eq!(ang_diff(a.wrapping_add(7), b.wrapping_add(7)), d);
        }

        #[test]
        fn fwd_is_unit_length(yaw in any::<u16>(), pitch in -16_000i16..=16_000) {
            let [x, y, z] = fwd(yaw, pitch);
            let l2 = i64::from(x) * i64::from(x) + i64::from(y) * i64::from(y) + i64::from(z) * i64::from(z);
            let err = (l2 - (1i64 << 60)).abs();
            // Each component carries at most ~1.5 units of error.
            prop_assert!(err <= 1i64 << 33, "err {}", err);
        }
    }
}
